/// <summary>
/// Pins the complete login exchange of kr-1256, cn-774 and tw-454 through the shared login binding:
/// every frame in order as its opcode name and full hex, for a stored character and for a new account.
/// </summary>
public sealed class LoginBurstPins
{
    /// <summary>Builds whose login the modern codec serves.</summary>
    public static TheoryData<string, int> Builds => new()
    {
        { "kr-1256", 1256 },
        { "cn-774", 774 },
        { "tw-454", 454 },
    };

    /// <summary>The launcher-ticket identity and the open (password) account name parse the same launcher body.</summary>
    [Theory]
    [MemberData(nameof(Builds))]
    public async Task LauncherAndOpenLoginDeliverTheSameIdentity(string build, int major)
    {
        await using var rig = await Rig.StartAsync(build, major);
        foreach (var identity in new[] { "bff-ticket:" + new string('a', 64), "open-account" })
            Assert.Equal(identity, LoginMessageCodec.ReadRequest(LauncherLogin(identity), rig.Values.Shape).Account);
    }

    /// <summary>The whole post-login burst is byte-pinned: opcode name and full hex, in order.</summary>
    [Theory]
    [MemberData(nameof(Builds))]
    public async Task LoginBurstIsPinned(string build, int major)
    {
        var pins = Pinned(build);
        var results = new Dictionary<bool, string[]>();
        foreach (var stored in new[] { true, false })
        {
            await using var rig = await Rig.StartAsync(build, major);
            var session = new RecordingSession(rig.Profile);
            await rig.Binding.SendAsync(session, Login(stored), default);
            var actual = session.Frames.Select(frame => $"{rig.Name(frame.Opcode)}={Convert.ToHexString(frame.Payload)}").ToArray();
            results[stored] = actual;
        }
        foreach (var stored in new[] { true, false })
            Assert.Equal(pins[stored], results[stored]);
    }

    /// <summary>The main menu install is kind 1; a kind 2 install crashes the client and must never appear at login.</summary>
    [Theory]
    [MemberData(nameof(Builds))]
    public async Task LoginMainMenuInstallIsKindOne(string build, int major)
    {
        await using var rig = await Rig.StartAsync(build, major);
        var session = new RecordingSession(rig.Profile);
        await rig.Binding.SendAsync(session, Login(stored: true), default);
        var mainMenu = Assert.Single(session.Frames, frame => frame.Opcode == rig.Opcodes.S2C("gspGotoRoom"));
        // The SessionSetting head is the same on all three builds: u16, i32, wstr, three u16, bool32, wstr, i32 kind.
        Assert.Equal(1u, System.Buffers.Binary.BinaryPrimitives.ReadUInt32LittleEndian(mainMenu.Payload.AsSpan(40)));
    }

    private static LoginSucceeded Login(bool stored) => new(
        1001, "account", "nick", 10, new DateTime(2026, 10, 16), 300001, [300001], null,
        stored ? CharacterBag : null, stored ? EquippedBag : null);

    private static IReadOnlyList<InventorySlotRecord> CharacterBag =>
    [
        new(1001, InventoryBag.CharacterBag, 0x0102030405060708, 201001, 3, 0),
        new(1001, InventoryBag.CharacterBag, 2, 300001, 1, InventorySlotRecord.WornFlagBit),
    ];

    private static IReadOnlyList<InventorySlotRecord> EquippedBag =>
    [
        new(1001, InventoryBag.EquippedBag, 2, 300001, 1, InventorySlotRecord.WornFlagBit),
    ];

    private static byte[] LauncherLogin(string account)
    {
        // kr-1256 sub_10C6A00: three strings, counted i32 vector, two i32 and one string.
        var buffer = new System.Buffers.ArrayBufferWriter<byte>();
        var writer = new PacketWriter(buffer);
        writer.WriteWideStringPrefixed(account);
        writer.WriteWideStringPrefixed(string.Empty);
        writer.WriteWideStringPrefixed(string.Empty);
        writer.WriteUInt32(0);
        writer.WriteInt32(0);
        writer.WriteInt32(0);
        writer.WriteWideStringPrefixed(string.Empty);
        return buffer.WrittenSpan.ToArray();
    }

    // Independent full-frame expectations, keyed by stored (true) or new account (false).
    private static IReadOnlyDictionary<bool, string[]> Pinned(string build) => build switch
    {
        "kr-1256" => new Dictionary<bool, string[]> { [true] = Kr1256Stored, [false] = Kr1256New },
        "cn-774" => new Dictionary<bool, string[]> { [true] = Cn774Stored, [false] = Cn774New },
        "tw-454" => new Dictionary<bool, string[]> { [true] = Tw454Stored, [false] = Tw454New },
        _ => throw new ArgumentOutOfRangeException(nameof(build), build, "No pin for this build."),
    };

