    private sealed class Rig : IAsyncDisposable
    {
        internal ClientProfile Profile { get; private init; } = null!;
        internal EventBus Events { get; } = new(NullLogger.Instance);
        internal LoginBinding Binding { get; private set; } = null!;
        internal LoginValues Values { get; private set; } = null!;
        internal IOpcodeTable Opcodes { get; private set; } = null!;
        private readonly ServiceRegistry _services = new();
        private readonly List<PluginContext> _contexts = [];
        private IDisposable _table = null!;
        private readonly Dictionary<ushort, string> _names = [];

        internal static async Task<Rig> StartAsync(string build, int major)
        {
            var rig = new Rig { Profile = new(build, build[..2], major, 0, 0, build) };
            var context = new PluginContext(
                new PluginRow { Id = "core.opcode-tables", Plugin = "core.opcode-tables", Source = "login-pin" },
                rig._services, rig.Events, NullLogger.Instance);
            rig._contexts.Add(context);
            await new OpcodeTableRegistryPlugin().ActivateAsync(context, default);
            var registry = rig._services.Get<IOpcodeTableRegistry>();
            rig._table = registry.Register(OpcodeTableLoader.Load(
                Path.Combine(Root(), "profiles", build, "opcodes.yaml"), rig.Profile));
            var opcodes = registry.ForProtocol(build + "/game");
            var tables = PacketTables.Load(Path.Combine(Root(), "packets"));
            var values = LoginValues.From(build, tables.ValuesOf(build));
            var inventory = new InventoryBinding(build + "/game", opcodes, tables, build);
            rig.Opcodes = opcodes;
            rig.Values = values;
            rig.Binding = new LoginBinding(build + "/game", values, opcodes.S2C("gspRepLogin"), opcodes, tables,
                build, rig._services, rig.Events, inventory, null, NullLogger.Instance);
            rig.Names();
            return rig;
        }

        internal string Name(ushort opcode) => _names.TryGetValue(opcode, out var name)
            ? name
            : throw new InvalidOperationException($"The login burst contains unregistered opcode {opcode}.");

        private void Names()
        {
            void Add(ushort? opcode, string name)
            {
                if (opcode is { } value) _names[value] = name;
            }
            Add(Opcodes.Find(PacketDirection.ServerToClient, "gspRepLogin"), "gspRepLogin");
            Add(Opcodes.Find(PacketDirection.ServerToClient, "gspUserStat"), "gspUserStat");
            Add(Opcodes.Find(PacketDirection.ServerToClient, "gspUserMoneyStat"), "gspUserMoneyStat");
            Add(Opcodes.Find(PacketDirection.ServerToClient, "gspUserPcroomStat"), "gspUserPcroomStat");
            Add(Opcodes.Find(PacketDirection.ServerToClient, "gspCenterList"), "gspCenterList");
            Add(Opcodes.Find(PacketDirection.ServerToClient, "gspUpdateParty"), "gspUpdateParty");
            Add(Opcodes.Find(PacketDirection.ServerToClient, "gspRepOption"), "gspRepOption");
            Add(Opcodes.Find(PacketDirection.ServerToClient, "gspInventoryUpdateAllInventorySlot"), "gspInventoryUpdateAllInventorySlot");
            Add(Opcodes.Find(PacketDirection.ServerToClient, "gspInventoryUpdateInventorySlots"), "gspInventoryUpdateInventorySlots");
            Add(Opcodes.Find(PacketDirection.ServerToClient, "gspUpdateAllArticleSlot"), "gspUpdateAllArticleSlot");
            Add(Opcodes.Find(PacketDirection.ServerToClient, "gspCashInvenUpdateAllInventorySlot"), "gspCashInvenUpdateAllInventorySlot");
            Add(Opcodes.Find(PacketDirection.ServerToClient, "gspGotoRoom"), "gspGotoRoom");
            Add(Opcodes.Find(PacketDirection.ServerToClient, "gspNotifyFirstMoveChannel"), "gspNotifyFirstMoveChannel");
        }

        public async ValueTask DisposeAsync()
        {
            _table.Dispose();
            foreach (var context in _contexts.AsEnumerable().Reverse()) await context.UnwindAsync();
        }
    }

    private sealed class RecordingSession : ISessionWithFeatures
    {
        internal RecordingSession(ClientProfile profile)
        {
            Profile = profile;
            this.SetLobbyPlayer(1001, pastLoginBurst: false);
        }

        public long Id => 1;
        public IConnection Connection { get; } = new Connection();
        public ISessionFeatures Features { get; } = new TestSessionFeatures();
        public ClientProfile Profile { get; }
        public ConcurrentDictionary<string, object> Items { get; } = new();
        internal List<(ushort Opcode, byte[] Payload)> Frames { get; } = [];

        public ValueTask SendAsync(ushort opcode, ReadOnlyMemory<byte> payload, CancellationToken ct)
        {
            ct.ThrowIfCancellationRequested();
            Frames.Add((opcode, payload.ToArray()));
            return ValueTask.CompletedTask;
        }
    }

    private sealed class Connection : IConnection
    {
        public long Id => 1;
        public EndPoint RemoteEndPoint => new IPEndPoint(IPAddress.Loopback, 1);
        public PipeReader Input => throw new NotSupportedException();
        public PipeWriter Output => throw new NotSupportedException();
        public ConcurrentDictionary<string, object> Items { get; } = new();
        public bool IsClosed => false;
        public ValueTask CloseAsync(string reason) => ValueTask.CompletedTask;
    }

    private static string Root()
    {
        for (var directory = new DirectoryInfo(AppContext.BaseDirectory); directory is not null; directory = directory.Parent)
            if (File.Exists(Path.Combine(directory.FullName, "BubbleFighter.Fantasy.sln"))) return directory.FullName;
        throw new InvalidOperationException("The test must run below the repository.");
    }
